# ============================================================================
# IN-MEMORY CACHE FOR BLAZING FAST RETRIEVAL
# ============================================================================
# Simple TTL cache for expensive endpoints
_cache: Dict[str, Dict[str, Any]] = {}
CACHE_TTL_SECONDS = 30  # 30-second cache for dashboard data

def get_cached(key: str) -> Optional[Any]:
    """Get cached value if not expired"""
    if key in _cache:
        entry = _cache[key]
        if time.time() - entry['timestamp'] < CACHE_TTL_SECONDS:
            return entry['data']
        del _cache[key]
    return None

def set_cached(key: str, data: Any) -> None:
    """Set cache entry with timestamp"""
    _cache[key] = {'data': data, 'timestamp': time.time()}

def clear_cache(prefix: str = None) -> None:
    """Clear cache entries, optionally by prefix"""
    global _cache
    if prefix:
        _cache = {k: v for k, v in _cache.items() if not k.startswith(prefix)}
    else:
        _cache = {}

# Database - Create Base first
Base = declarative_base()

# Then create engine
# SQLite-specific settings
if DATABASE_URL.startswith("sqlite"):
    engine = create_engine(
        DATABASE_URL,
        connect_args={"check_same_thread": False}
    )
else:
    engine = create_engine(
        DATABASE_URL,
        pool_pre_ping=True,
        pool_size=5,
        max_overflow=10,
        pool_recycle=3600
    )
SessionLocal = sessionmaker(autocommit=False, autoflush=False, bind=engine)

# Initialize background scheduler for auto-sync
scheduler = AsyncIOScheduler()

def get_db():
    db = SessionLocal()
    try:
        yield db
    finally:
        db.close()

