        # Tool execution functions
        async def execute_send_email(args):
            subject = args.get("subject", "CRM Update")
            content_type = args.get("content_type", "custom")
            timeframe = args.get("timeframe", "today")

            # Get relevant data based on content type
            if content_type == "task_summary":
                today = datetime.now().date()
                tomorrow = today + timedelta(days=1)
                week_end = today + timedelta(days=7)

                # Get ALL tasks for this user
                all_user_tasks = db.query(Task).filter(Task.owner_id == current_user.id).all()

                # Filter based on timeframe
                if timeframe == "tomorrow":
                    tasks = [t for t in all_user_tasks if t.due_date and t.due_date.date() == tomorrow and t.status != "completed"]
                elif timeframe == "this_week":
                    tasks = [t for t in all_user_tasks if t.due_date and today <= t.due_date.date() <= week_end and t.status != "completed"]
                elif timeframe == "outstanding" or timeframe == "priorities":
                    # Get ALL outstanding (not completed) tasks
                    tasks = [t for t in all_user_tasks if t.status != "completed"]
                    # Sort by priority and due date
                    priority_order = {"high": 0, "medium": 1, "low": 2, None: 3}
                    tasks.sort(key=lambda x: (priority_order.get(x.priority, 3), x.due_date or datetime.max))
                elif timeframe == "overdue":
                    tasks = [t for t in all_user_tasks if t.due_date and t.due_date.date() < today and t.status != "completed"]
                else:  # today
                    tasks = [t for t in all_user_tasks if t.due_date and t.due_date.date() == today and t.status != "completed"]

                # Build detailed task list
                task_lines = []
                for i, t in enumerate(tasks[:10], 1):
                    line = f"{i}. {t.title}"
                    details = []
                    if t.priority:
                        details.append(f"Priority: {t.priority.upper()}")
                    if t.due_date:
                        details.append(f"Due: {t.due_date.strftime('%m/%d/%Y %I:%M %p')}")
                    if t.status:
                        details.append(f"Status: {t.status}")
                    if t.description:
                        details.append(f"Notes: {t.description[:100]}")
                    if details:
                        line += f"\n   {' | '.join(details)}"
                    task_lines.append(line)

                task_list = "\n\n".join(task_lines)

                if timeframe in ["outstanding", "priorities"]:
                    content = f"You have {len(tasks)} outstanding task(s). Here are your top priorities:\n\n{task_list if task_list else 'No outstanding tasks - great job!'}"
                else:
                    content = f"Here are your tasks for {timeframe}:\n\n{task_list if task_list else 'No tasks scheduled.'}"

            elif content_type == "pipeline_update":
                leads = db.query(Lead).filter(Lead.owner_id == current_user.id).all()
                stages = {}
                for lead in leads:
                    stage = str(lead.stage) if lead.stage else "New"
                    if stage not in stages:
                        stages[stage] = 0
                    stages[stage] += 1

                stage_summary = "\n".join([f"• {stage}: {count} leads" for stage, count in stages.items()])
                content = f"Pipeline Summary:\n\n{stage_summary}\n\nTotal: {len(leads)} leads"
            else:
                content = args.get("content", f"Custom update requested: {subject}")

            # Actually send the email via SMTP
            email_sent = False
            try:
                import smtplib
                from email.mime.text import MIMEText
                from email.mime.multipart import MIMEMultipart
                import os as os_module

                smtp_host = os_module.environ.get("SMTP_HOST", "smtp.gmail.com")
                smtp_port = int(os_module.environ.get("SMTP_PORT", "587"))
                smtp_user = os_module.environ.get("SMTP_USER", "")
                smtp_pass = os_module.environ.get("SMTP_PASS", "")

                if smtp_user and smtp_pass:
                    msg = MIMEMultipart()
                    msg['From'] = smtp_user
                    msg['To'] = current_user.email
                    msg['Subject'] = subject

                    # Create HTML version
                    html_content = f"""
                    <html>
                    <body style="font-family: Arial, sans-serif; line-height: 1.6;">
                        <h2>{subject}</h2>
                        <pre style="white-space: pre-wrap;">{content}</pre>
                        <hr>
                        <p style="color: #666; font-size: 12px;">Sent from Pipeline 360 CRM</p>
                    </body>
                    </html>
                    """
                    msg.attach(MIMEText(html_content, 'html'))

                    with smtplib.SMTP(smtp_host, smtp_port) as server:
                        server.starttls()
                        server.login(smtp_user, smtp_pass)
                        server.send_message(msg)
                    email_sent = True
            except Exception as e:
                logger.warning(f"Email send failed: {e}")

            await log_ai_action_to_mission_control(
                db=db,
                agent_name="Email Tool",
                action_type="send_email",
                user_id=current_user.id,
                context={"subject": subject, "content_type": content_type, "email_sent": email_sent},
                autonomy_level="autonomous",
                status="completed" if email_sent else "logged"
            )

            return {
                "success": True,
                "email_sent": email_sent,
                "message": f"Email {'sent' if email_sent else 'prepared'} for {current_user.email}",
                "subject": subject,
                "content": content,
                "preview": content[:500]
            }

        async def execute_get_tasks(args):
            timeframe = args.get("timeframe", "today")
            status_filter = args.get("status", "all")
            today = datetime.now().date()

            # Query tasks WITH related loan and lead info for borrower context
            task_query = text("""
                SELECT t.id, t.title, t.due_date, t.status, t.priority, t.description,
                       COALESCE(ln.borrower_name, ld.name, t.related_contact_name) as borrower_name,
                       ln.amount as loan_amount, ln.stage as loan_stage, ln.loan_number,
                       t.loan_id, t.lead_id
                FROM tasks t
                LEFT JOIN loans ln ON t.loan_id = ln.id
                LEFT JOIN leads ld ON t.lead_id = ld.id
                WHERE t.owner_id = :user_id
                AND t.status != 'completed'
                ORDER BY
                    CASE WHEN t.priority = 'high' THEN 1 WHEN t.priority = 'medium' THEN 2 ELSE 3 END,
                    t.due_date ASC NULLS LAST
            """)
            result = db.execute(task_query, {"user_id": current_user.id})
            all_task_rows = result.fetchall()

            # Filter based on timeframe
            filtered_tasks = []
            for row in all_task_rows:
                task_date = row[2].date() if row[2] else None
                if timeframe == "today":
                    if task_date == today:
                        filtered_tasks.append(row)
                elif timeframe == "tomorrow":
                    tomorrow = today + timedelta(days=1)
                    if task_date == tomorrow:
                        filtered_tasks.append(row)
                elif timeframe == "this_week":
                    week_end = today + timedelta(days=7)
                    if task_date and today <= task_date <= week_end:
                        filtered_tasks.append(row)
                elif timeframe == "overdue":
                    if task_date and task_date < today:
                        filtered_tasks.append(row)
                else:  # all outstanding
                    filtered_tasks.append(row)

            return {
                "count": len(filtered_tasks),
                "timeframe": timeframe,
                "tasks": [{
                    "id": r[0],
                    "title": r[1],
                    "due_date": r[2].isoformat() if r[2] else None,
                    "status": r[3],
                    "priority": r[4],
                    "description": r[5][:100] if r[5] else None,
                    "borrower_name": r[6],
                    "loan_amount": float(r[7]) if r[7] else None,
                    "loan_stage": r[8],
                    "loan_number": r[9],
                    "loan_id": r[10],
                    "lead_id": r[11]
                } for r in filtered_tasks[:15]]
            }

        async def execute_create_task(args):
            title = args.get("title")
            description = args.get("description", "")
            due_date_str = args.get("due_date")
            priority = args.get("priority", "medium")
            lead_id = args.get("lead_id")

            due_date = None
            if due_date_str:
                try:
                    due_date = datetime.strptime(due_date_str, "%Y-%m-%d")
                except:
                    due_date = datetime.now() + timedelta(days=1)

            new_task = Task(title=title, description=description, due_date=due_date, priority=priority, status="pending", owner_id=current_user.id, lead_id=lead_id)
            db.add(new_task)
            db.commit()
            db.refresh(new_task)

            await log_ai_action_to_mission_control(db=db, agent_name="Task Tool", action_type="create_task", user_id=current_user.id, context={"task_id": new_task.id, "title": title}, autonomy_level="autonomous", status="completed")

            return {"success": True, "task_id": new_task.id, "message": f"Task '{title}' created successfully"}

        async def execute_search_leads(args):
            query_str = args.get("query", "")
            status = args.get("status")
            limit = args.get("limit", 5)

            query = db.query(Lead).filter(Lead.owner_id == current_user.id)
            if query_str:
                search = f"%{query_str}%"
                query = query.filter((Lead.name.ilike(search)) | (Lead.email.ilike(search)) | (Lead.phone.ilike(search)))
            if status:
                query = query.filter(Lead.stage == status)

            leads = query.limit(limit).all()
            return {"count": len(leads), "leads": [{"id": l.id, "name": f"{l.name}", "email": l.email, "phone": l.phone, "status": str(l.stage) if l.stage else None} for l in leads]}

        async def execute_get_pipeline(args):
            include_details = args.get("include_details", False)

            # Get leads
            leads = db.query(Lead).filter(Lead.owner_id == current_user.id).all()

            # Get loans using raw SQL to avoid enum issues
            try:
                loan_rows = db.execute(
                    text("""SELECT id, loan_number, borrower_name, stage, amount, processor, underwriter, days_in_stage, closing_date
                            FROM loans WHERE loan_officer_id = :user_id"""),
                    {"user_id": current_user.id}
                ).fetchall()
            except Exception as e:
                logger.error(f"Error fetching loans for pipeline: {e}")
                loan_rows = []

            # Lead stages
            lead_stages = {}
            for lead in leads:
                stage = str(lead.stage) if lead.stage else "New"
                if stage not in lead_stages:
                    lead_stages[stage] = {"count": 0, "items": []}
                lead_stages[stage]["count"] += 1
                if include_details:
                    lead_stages[stage]["items"].append({"id": lead.id, "name": f"{lead.name}", "type": "lead"})

            # Loan stages
            loan_stages = {}
            for loan in loan_rows:
                stage = str(loan.stage) if loan.stage else "Unknown"
                if stage not in loan_stages:
                    loan_stages[stage] = {"count": 0, "items": []}
                loan_stages[stage]["count"] += 1
                if include_details:
                    borrower_name = loan.borrower_name if loan.borrower_name else f"Loan #{loan.id}"
                    loan_stages[stage]["items"].append({
                        "id": loan.id,
                        "name": borrower_name,
                        "amount": float(loan.amount) if loan.amount else 0,
                        "processor": loan.processor,
                        "underwriter": loan.underwriter,
                        "days_in_stage": loan.days_in_stage,
                        "closing_date": loan.closing_date.isoformat() if loan.closing_date else None,
                        "type": "loan"
                    })

            return {
                "total_leads": len(leads),
                "total_loans": len(loan_rows),
                "lead_stages": lead_stages,
                "loan_stages": loan_stages,
                "summary": f"{len(leads)} leads, {len(loan_rows)} active loans"
            }

        async def execute_schedule_followup(args):
            lead_id = args.get("lead_id")
            lead_name = args.get("lead_name")
            followup_type = args.get("followup_type", "call")
            scheduled_time = args.get("scheduled_time", "tomorrow")
            notes = args.get("notes", "")

            if not lead_id and lead_name:
                search = f"%{lead_name}%"
                lead = db.query(Lead).filter(Lead.owner_id == current_user.id, (Lead.name.ilike(search))).first()
                if lead:
                    lead_id = lead.id

            due_date = datetime.now() + timedelta(days=1)

            task = Task(title=f"Follow-up {followup_type} with lead", description=notes, due_date=due_date, priority="high", status="pending", owner_id=current_user.id, lead_id=lead_id)
            db.add(task)
            db.commit()

            await log_ai_action_to_mission_control(db=db, agent_name="Followup Tool", action_type="schedule_followup", user_id=current_user.id, context={"lead_id": lead_id, "type": followup_type}, autonomy_level="autonomous", status="completed")

            return {"success": True, "message": f"Follow-up {followup_type} scheduled", "task_id": task.id}

        async def execute_update_lead(args):
            lead_id = args.get("lead_id")
            lead_name = args.get("lead_name")

            if not lead_id and lead_name:
                search = f"%{lead_name}%"
                lead = db.query(Lead).filter(Lead.owner_id == current_user.id, (Lead.name.ilike(search))).first()
            else:
                lead = db.query(Lead).filter(Lead.id == lead_id).first()

            if not lead:
                return {"success": False, "message": "Lead not found"}

            if args.get("status"):
                lead.stage = args["status"]
            if args.get("loan_stage"):
                lead.loan_stage = args["loan_stage"]
            db.commit()

            return {"success": True, "message": f"Lead {lead.name} updated", "lead_id": lead.id}

        async def execute_get_metrics(args):
            leads = db.query(Lead).filter(Lead.owner_id == current_user.id).all()
            tasks = db.query(Task).filter(Task.owner_id == current_user.id).all()

            metrics = {"total_leads": len(leads), "total_tasks": len(tasks), "completed_tasks": len([t for t in tasks if t.status == "completed"]), "pipeline_stages": {}}
            for lead in leads:
                stage = str(lead.stage) if lead.stage else "New"
                if stage not in metrics["pipeline_stages"]:
                    metrics["pipeline_stages"][stage] = 0
                metrics["pipeline_stages"][stage] += 1

            return metrics

        async def execute_get_market_intelligence(args):
            """Fetch real-time market data for rate lock guidance (cached for 5 minutes)"""
            import httpx
            from performance_cache import get_cached, set_cached, cache_key

            lock_days = args.get("lock_days", 30)

            # Check cache first (market data cached for 5 minutes)
            cache_k = cache_key("market_intelligence", lock_days)
            cached_result = get_cached(cache_k)
            if cached_result:
                return cached_result

            # Default market data (will be updated with real data if available)
            treasury_10yr = 4.067
            treasury_2yr = 3.504
            mortgage_30yr = 6.875
            mbs_price = 102.21
            mbs_change = 0.08

            # Try to fetch real Treasury data from FRED API
            fred_api_key = "1dc7b79a0de274ac6198c520405425a0"
            try:
                async with httpx.AsyncClient(timeout=5.0) as client:
                    # Fetch 10-Year Treasury
                    resp_10yr = await client.get(
                        f"https://api.stlouisfed.org/fred/series/observations",
                        params={
                            "series_id": "DGS10",
                            "api_key": fred_api_key,
                            "file_type": "json",
                            "limit": 1,
                            "sort_order": "desc"
                        }
                    )
                    if resp_10yr.status_code == 200:
                        data = resp_10yr.json()
                        if data.get("observations") and data["observations"][0].get("value") != ".":
                            treasury_10yr = float(data["observations"][0]["value"])

                    # Fetch 2-Year Treasury
                    resp_2yr = await client.get(
                        f"https://api.stlouisfed.org/fred/series/observations",
                        params={
                            "series_id": "DGS2",
                            "api_key": fred_api_key,
                            "file_type": "json",
                            "limit": 1,
                            "sort_order": "desc"
                        }
                    )
                    if resp_2yr.status_code == 200:
                        data = resp_2yr.json()
                        if data.get("observations") and data["observations"][0].get("value") != ".":
                            treasury_2yr = float(data["observations"][0]["value"])

                    # Fetch 30-Year Mortgage Rate
                    resp_mtg = await client.get(
                        f"https://api.stlouisfed.org/fred/series/observations",
                        params={
                            "series_id": "MORTGAGE30US",
                            "api_key": fred_api_key,
                            "file_type": "json",
                            "limit": 1,
                            "sort_order": "desc"
                        }
                    )
                    if resp_mtg.status_code == 200:
                        data = resp_mtg.json()
                        if data.get("observations") and data["observations"][0].get("value") != ".":
                            mortgage_30yr = float(data["observations"][0]["value"])

            except Exception as e:
                logger.warning(f"Could not fetch FRED data, using defaults: {e}")

            # Calculate yield curve spread
            yield_spread = (treasury_10yr - treasury_2yr) * 100  # in bps

            # Calculate MBS price estimate based on treasury (simplified model)
            # MBS typically trades at premium when rates are lower
            mbs_price = 100 + (6.5 - mortgage_30yr) * 2  # Simplified pricing model
            mbs_price = round(max(98, min(104, mbs_price)), 2)

            # Calculate volatility score (1-10)
            vol_score = 5  # Base
            if abs(yield_spread) < 20:  # Flat/inverted curve = higher volatility
                vol_score += 2
            if treasury_10yr > 4.5:  # High rates = higher volatility
                vol_score += 1
            if treasury_10yr < 3.8:  # Low rates = lower volatility
                vol_score -= 1
            vol_score = max(1, min(10, vol_score))

            volatility = "low" if vol_score <= 3 else "high" if vol_score >= 7 else "moderate"

            # Calculate lock score based on market conditions
            lock_score = 50  # Base score

            # Adjust for treasury level
            if treasury_10yr > 4.5:
                lock_score += 15  # High rates - lock to avoid further increases
            elif treasury_10yr < 3.9:
                lock_score -= 10  # Low rates - might improve further

            # Adjust for yield curve
            if yield_spread < 0:
                lock_score += 10  # Inverted curve - economic uncertainty, lock
            elif yield_spread > 100:
                lock_score -= 5  # Healthy spread - rates may be stable

            # Adjust for closing timeline
            if lock_days <= 15:
                lock_score += 15  # Short timeline - lock for certainty
            elif lock_days >= 45:
                lock_score -= 10  # Long timeline - can wait for improvements

            lock_score = max(20, min(90, lock_score))

            # Determine recommendation
            if lock_score >= 70:
                action = "LOCK"
                action_reason = "Market conditions and timeline favor locking now to secure your rate"
                urgency = "high"
            elif lock_score >= 55:
                action = "CAUTIOUS LOCK"
                action_reason = "Moderate conditions - recommend locking if closing within 30 days"
                urgency = "moderate"
            elif lock_score >= 40:
                action = "MONITOR"
                action_reason = "Market is stable - monitor daily for better entry point"
                urgency = "low"
            else:
                action = "FLOAT"
                action_reason = "Conditions suggest potential rate improvements - float with daily monitoring"
                urgency = "low"

            result = {
                "success": True,
                "lock_days": lock_days,
                "current_rates": {
                    "30yr_fixed": mortgage_30yr,
                    "10yr_treasury": treasury_10yr,
                    "2yr_treasury": treasury_2yr
                },
                "mbs": {
                    "price": mbs_price,
                    "change": mbs_change,
                    "change_direction": "up" if mbs_change > 0 else "down" if mbs_change < 0 else "flat"
                },
                "yield_curve": {
                    "spread_bps": round(yield_spread, 0),
                    "status": "inverted" if yield_spread < 0 else "flat" if yield_spread < 50 else "normal"
                },
                "volatility": {
                    "level": volatility,
                    "score": vol_score
                },
                "recommendation": {
                    "action": action,
                    "lock_score": lock_score,
                    "urgency": urgency,
                    "reason": action_reason
                },
                "guidance": f"**Rate Lock Guidance ({lock_days}-day lock):**\n\n"
                           f"**Recommendation: {action}** (Score: {lock_score}/100)\n\n"
                           f"**Current Market Data:**\n"
                           f"• 30-Year Fixed: {mortgage_30yr}%\n"
                           f"• 10-Year Treasury: {treasury_10yr}%\n"
                           f"• 2-Year Treasury: {treasury_2yr}%\n"
                           f"• Yield Curve Spread: {round(yield_spread)}bps\n"
                           f"• MBS 6.0 Price: {mbs_price}\n"
                           f"• Market Volatility: {volatility.title()} ({vol_score}/10)\n\n"
                           f"**Analysis:** {action_reason}"
            }

            # Cache market data for 5 minutes (rates don't change that frequently)
            set_cached(cache_k, result, 300)
            return result

