        async def execute_get_loan_details(args):
            """Get comprehensive loan details including milestones, title, appraisal, insurance, CTC needs"""
            loan_id = args.get("loan_id")
            borrower_name = args.get("borrower_name")
            loan_number = args.get("loan_number")

            # Use raw SQL to avoid enum deserialization issues
            loan = None
            try:
                if loan_id:
                    loan = db.execute(
                        text("""SELECT id, loan_number, borrower_name, coborrower_name, stage, program, amount, rate,
                                       closing_date, days_in_stage, sla_status, property_address,
                                       loan_officer_name, processor, underwriter, closer
                                FROM loans WHERE id = :loan_id"""),
                        {"loan_id": loan_id}
                    ).fetchone()
                elif loan_number:
                    loan = db.execute(
                        text("""SELECT id, loan_number, borrower_name, coborrower_name, stage, program, amount, rate,
                                       closing_date, days_in_stage, sla_status, property_address,
                                       loan_officer_name, processor, underwriter, closer
                                FROM loans WHERE loan_number = :loan_number"""),
                        {"loan_number": loan_number}
                    ).fetchone()
                elif borrower_name:
                    loan = db.execute(
                        text("""SELECT id, loan_number, borrower_name, coborrower_name, stage, program, amount, rate,
                                       closing_date, days_in_stage, sla_status, property_address,
                                       loan_officer_name, processor, underwriter, closer
                                FROM loans WHERE loan_officer_id = :user_id
                                AND (LOWER(borrower_name) LIKE LOWER(:search) OR LOWER(coborrower_name) LIKE LOWER(:search))
                                LIMIT 1"""),
                        {"user_id": current_user.id, "search": f"%{borrower_name}%"}
                    ).fetchone()
            except Exception as e:
                logger.error(f"Error finding loan: {e}")
                return {"success": False, "message": f"Error finding loan: {str(e)}"}

            if not loan:
                return {"success": False, "message": "Loan not found. Please provide a valid loan ID, loan number, or borrower name."}

            # Get milestones
            milestones = db.query(Milestone).filter(Milestone.loan_id == loan.id).order_by(Milestone.target_date).all()
            milestone_list = []
            for m in milestones:
                milestone_list.append({
                    "name": m.name,
                    "status": m.status,
                    "target_date": m.target_date.isoformat() if m.target_date else None,
                    "completed_date": m.completed_date.isoformat() if m.completed_date else None,
                    "is_overdue": m.target_date and m.target_date.date() < datetime.now().date() and m.status != "completed"
                })

            # Get workflow tasks for this loan
            try:
                workflow_tasks = db.execute(
                    text("""
                        SELECT task_key, status, completed_at, due_date
                        FROM loan_workflow_tasks
                        WHERE loan_id = :loan_id
                    """),
                    {"loan_id": loan.id}
                ).fetchall()
                ctc_checklist = []
                for wt in workflow_tasks:
                    if wt.status != "completed":
                        ctc_checklist.append({
                            "task": wt.task_key.replace("_", " ").title(),
                            "status": wt.status,
                            "due": wt.due_date.isoformat() if wt.due_date else None
                        })
            except:
                ctc_checklist = []

            # Get activities/notes
            activities = db.query(Activity).filter(Activity.loan_id == loan.id).order_by(Activity.created_at.desc()).limit(10).all()
            activity_list = [{"type": a.activity_type, "description": a.description, "date": a.created_at.isoformat()} for a in activities]

            stage_name = str(loan.stage).replace("LoanStage.", "") if loan.stage else "Unknown"

            return {
                "success": True,
                "loan": {
                    "id": loan.id,
                    "loan_number": loan.loan_number,
                    "borrower_name": loan.borrower_name,
                    "coborrower_name": loan.coborrower_name,
                    "stage": stage_name,
                    "days_in_stage": loan.days_in_stage,
                    "sla_status": loan.sla_status,
                    "program": loan.program,
                    "amount": float(loan.amount) if loan.amount else 0,
                    "rate": float(loan.rate) if loan.rate else None,
                    "closing_date": loan.closing_date.isoformat() if loan.closing_date else None,
                    "property_address": loan.property_address
                },
                "team": {
                    "loan_officer": loan.loan_officer_name,
                    "processor": loan.processor,
                    "underwriter": loan.underwriter,
                    "closer": loan.closer
                },
                "milestones": milestone_list,
                "ctc_checklist": ctc_checklist,
                "recent_activity": activity_list,
                "guidance": f"Loan for {loan.borrower_name} is in {stage_name} stage. " +
                           (f"Closing date: {loan.closing_date.strftime('%B %d, %Y')}. " if loan.closing_date else "") +
                           (f"{len(ctc_checklist)} items remaining for Clear to Close." if ctc_checklist else "")
            }

        async def execute_get_lead_details(args):
            """Get comprehensive lead details including contact info, financial snapshot, activity history"""
            lead_id = args.get("lead_id")
            lead_name = args.get("lead_name")

            lead = None
            if lead_id:
                lead = db.query(Lead).filter(Lead.id == lead_id).first()
            elif lead_name:
                search = f"%{lead_name}%"
                lead = db.query(Lead).filter(
                    Lead.owner_id == current_user.id,
                    Lead.name.ilike(search)
                ).first()

            if not lead:
                return {"success": False, "message": "Lead not found"}

            # Get activities
            activities = db.query(Activity).filter(Activity.lead_id == lead.id).order_by(Activity.created_at.desc()).limit(10).all()
            activity_list = [{"type": a.activity_type, "description": a.description, "date": a.created_at.isoformat()} for a in activities]

            # Get tasks for this lead
            tasks = db.query(Task).filter(Task.lead_id == lead.id, Task.status != "completed").all()
            task_list = [{"title": t.title, "due": t.due_date.isoformat() if t.due_date else None, "priority": t.priority} for t in tasks]

            stage_name = str(lead.stage).replace("LeadStage.", "") if lead.stage else "NEW"

            return {
                "success": True,
                "lead": {
                    "id": lead.id,
                    "name": lead.name,
                    "email": lead.email,
                    "phone": lead.phone,
                    "stage": stage_name,
                    "loan_stage": str(lead.loan_stage) if lead.loan_stage else None,
                    "source": lead.source,
                    "created_at": lead.created_at.isoformat() if lead.created_at else None
                },
                "financial_snapshot": {
                    "credit_score": lead.credit_score,
                    "dti": float(lead.dti) if lead.dti else None,
                    "income": float(lead.income) if lead.income else None,
                    "loan_amount": float(lead.loan_amount) if lead.loan_amount else None,
                    "property_value": float(lead.property_value) if lead.property_value else None,
                    "ltv": round(float(lead.loan_amount) / float(lead.property_value) * 100, 1) if lead.loan_amount and lead.property_value else None
                },
                "property": {
                    "address": lead.property_address,
                    "city": lead.property_city,
                    "state": lead.property_state,
                    "zip": lead.property_zip,
                    "type": lead.property_type,
                    "purpose": lead.loan_purpose
                },
                "referral_source": lead.referral_source,
                "recent_activity": activity_list,
                "pending_tasks": task_list,
                "notes": lead.notes
            }

        async def execute_get_mum_clients(args):
            """Get Mortgage Under Management clients"""
            filter_type = args.get("filter", "all")
            limit = args.get("limit", 20)

            try:
                # Get MUM clients from the mum_clients table
                mum_query = db.execute(
                    text("""
                        SELECT id, client_name, email, phone, original_loan_date, loan_amount,
                               current_rate, equity_estimate, refinance_eligible, amr_status,
                               engagement_score, last_contact_date, next_action_date, property_address
                        FROM mum_clients
                        WHERE loan_officer_id = :user_id
                        ORDER BY next_action_date ASC NULLS LAST
                        LIMIT :limit
                    """),
                    {"user_id": current_user.id, "limit": limit}
                ).fetchall()

                clients = []
                for c in mum_query:
                    client = {
                        "id": c.id,
                        "name": c.client_name,
                        "email": c.email,
                        "phone": c.phone,
                        "loan_date": c.original_loan_date.isoformat() if c.original_loan_date else None,
                        "loan_amount": float(c.loan_amount) if c.loan_amount else None,
                        "current_rate": float(c.current_rate) if c.current_rate else None,
                        "equity_estimate": float(c.equity_estimate) if c.equity_estimate else None,
                        "refinance_eligible": c.refinance_eligible,
                        "amr_status": c.amr_status,
                        "engagement_score": c.engagement_score,
                        "last_contact": c.last_contact_date.isoformat() if c.last_contact_date else None,
                        "next_action": c.next_action_date.isoformat() if c.next_action_date else None,
                        "property": c.property_address
                    }

                    # Apply filters
                    if filter_type == "refinance_opportunity" and not c.refinance_eligible:
                        continue
                    elif filter_type == "amr_due" and c.amr_status != "due":
                        continue
                    elif filter_type == "needs_contact":
                        if c.last_contact_date and (datetime.now().date() - c.last_contact_date).days < 90:
                            continue

                    clients.append(client)

                return {
                    "success": True,
                    "total_mum_clients": len(clients),
                    "filter": filter_type,
                    "clients": clients[:limit]
                }
            except Exception as e:
                logger.error(f"Error fetching MUM clients: {e}")
                return {"success": False, "message": f"MUM clients feature not available: {str(e)}"}

        async def execute_get_referral_partners(args):
            """Get referral partner information"""
            partner_id = args.get("partner_id")
            partner_name = args.get("partner_name")
            category = args.get("category", "all")
            limit = args.get("limit", 10)

            try:
                where_clauses = ["rp.user_id = :user_id"]
                params = {"user_id": current_user.id, "limit": limit}

                if partner_id:
                    where_clauses.append("rp.id = :partner_id")
                    params["partner_id"] = partner_id
                if partner_name:
                    where_clauses.append("rp.name ILIKE :partner_name")
                    params["partner_name"] = f"%{partner_name}%"
                if category and category != "all":
                    where_clauses.append("rp.category = :category")
                    params["category"] = category

                where_sql = " AND ".join(where_clauses)

                partners = db.execute(
                    text(f"""
                        SELECT id, name, email, phone, company, category,
                               loyalty_tier, reciprocity_score, total_referrals,
                               referrals_this_year, last_referral_date, engagement_status
                        FROM referral_partners rp
                        WHERE {where_sql}
                        ORDER BY reciprocity_score DESC
                        LIMIT :limit
                    """),
                    params
                ).fetchall()

                partner_list = [{
                    "id": p.id,
                    "name": p.name,
                    "email": p.email,
                    "phone": p.phone,
                    "company": p.company,
                    "category": p.category,
                    "loyalty_tier": p.loyalty_tier,
                    "reciprocity_score": p.reciprocity_score,
                    "total_referrals": p.total_referrals,
                    "referrals_this_year": p.referrals_this_year,
                    "last_referral": p.last_referral_date.isoformat() if p.last_referral_date else None,
                    "status": p.engagement_status
                } for p in partners]

                return {
                    "success": True,
                    "total_partners": len(partner_list),
                    "partners": partner_list
                }
            except Exception as e:
                logger.error(f"Error fetching referral partners: {e}")
                return {"success": False, "message": f"Referral partners data not available: {str(e)}"}

        async def execute_get_sla_dashboard(args):
            """Get SLA tracking dashboard with detailed bottleneck analysis"""
            view = args.get("view", "summary")

            # SLA target days by stage (industry standards)
            SLA_TARGETS = {
                "Application": 2,
                "APPLICATION": 2,
                "Disclosed": 3,
                "DISCLOSED": 3,
                "Processing": 5,
                "PROCESSING": 5,
                "Submitted": 2,
                "SUBMITTED": 2,
                "Conditional": 3,
                "CONDITIONAL": 3,
                "CTC": 2,
                "Clear to Close": 2,
                "CLEAR_TO_CLOSE": 2,
                "Docs": 2,
                "DOCS": 2,
                "Funding": 1,
                "FUNDING": 1
            }

            try:
                # Get comprehensive loan data with all relevant fields
                loan_data = db.execute(
                    text("""
                        SELECT
                            id,
                            loan_number,
                            borrower_name,
                            coborrower_name,
                            stage::text as stage,
                            amount,
                            rate,
                            days_in_stage,
                            sla_status,
                            closing_date,
                            processor,
                            underwriter,
                            closer,
                            property_address,
                            updated_at
                        FROM loans
                        WHERE loan_officer_id = :user_id
                        AND stage::text NOT IN ('Funded', 'Withdrawn', 'Closed', 'FUNDED', 'WITHDRAWN', 'CLOSED')
                        ORDER BY days_in_stage DESC NULLS LAST
                    """),
                    {"user_id": current_user.id}
                ).fetchall()

                bottlenecks = []
                at_risk = []
                stage_analysis = {}
                total_stuck_volume = 0

                for loan in loan_data:
                    stage = str(loan.stage) if loan.stage else "Unknown"
                    days = loan.days_in_stage or 0
                    amount = float(loan.amount) if loan.amount else 0
                    target_days = SLA_TARGETS.get(stage, 5)
                    variance = days - target_days

                    # Track stage metrics
                    if stage not in stage_analysis:
                        stage_analysis[stage] = {
                            "count": 0,
                            "total_days": 0,
                            "total_volume": 0,
                            "target_days": target_days,
                            "stuck_loans": []
                        }
                    stage_analysis[stage]["count"] += 1
                    stage_analysis[stage]["total_days"] += days
                    stage_analysis[stage]["total_volume"] += amount

                    # Identify bottlenecks (loans exceeding SLA target by 50%+)
                    if days > target_days * 1.5:
                        loan_detail = {
                            "loan_id": loan.id,
                            "loan_number": loan.loan_number,
                            "borrower_name": loan.borrower_name,
                            "coborrower_name": loan.coborrower_name,
                            "amount": amount,
                            "stage": stage,
                            "days_in_stage": days,
                            "target_days": target_days,
                            "days_over_sla": days - target_days,
                            "processor": loan.processor,
                            "underwriter": loan.underwriter,
                            "closer": loan.closer,
                            "closing_date": loan.closing_date.isoformat() if loan.closing_date else None,
                            "last_updated": loan.updated_at.isoformat() if loan.updated_at else None
                        }
                        bottlenecks.append(loan_detail)
                        stage_analysis[stage]["stuck_loans"].append(loan_detail)
                        total_stuck_volume += amount

                    # Identify at-risk loans
                    if loan.sla_status in ["at_risk", "breached"] or variance > 0:
                        at_risk.append({
                            "loan_id": loan.id,
                            "loan_number": loan.loan_number,
                            "borrower_name": loan.borrower_name,
                            "amount": amount,
                            "stage": stage,
                            "days_in_stage": days,
                            "sla_status": loan.sla_status or ("breached" if variance > 2 else "at_risk"),
                            "days_over_target": variance if variance > 0 else 0,
                            "closing_date": loan.closing_date.isoformat() if loan.closing_date else None
                        })

                # Calculate stage averages and identify worst stages
                stage_bottlenecks = []
                for stage, data in stage_analysis.items():
                    avg_days = data["total_days"] / data["count"] if data["count"] > 0 else 0
                    variance = avg_days - data["target_days"]
                    if variance > 0:
                        stage_bottlenecks.append({
                            "stage": stage,
                            "loan_count": data["count"],
                            "avg_days": round(avg_days, 1),
                            "target_days": data["target_days"],
                            "variance_days": round(variance, 1),
                            "total_volume": data["total_volume"],
                            "stuck_loans": data["stuck_loans"][:5]  # Top 5 stuck in this stage
                        })

                stage_bottlenecks = sorted(stage_bottlenecks, key=lambda x: x["variance_days"], reverse=True)

                # Generate specific guidance
                guidance_parts = []
                if bottlenecks:
                    worst = bottlenecks[0]
                    guidance_parts.append(f"CRITICAL: {worst['borrower_name']}'s ${worst['amount']:,.0f} loan is {worst['days_in_stage']} days in {worst['stage']} ({worst['days_over_sla']} days over SLA).")
                if stage_bottlenecks:
                    worst_stage = stage_bottlenecks[0]
                    guidance_parts.append(f"Stage bottleneck: {worst_stage['stage']} averaging {worst_stage['avg_days']} days vs {worst_stage['target_days']}-day target.")
                if not bottlenecks and not at_risk:
                    guidance_parts.append("Pipeline is healthy - no SLA issues detected.")

                return {
                    "success": True,
                    "view": view,
                    "summary": {
                        "total_active_loans": len(loan_data),
                        "bottlenecks_count": len(bottlenecks),
                        "at_risk_count": len(at_risk),
                        "stuck_volume": total_stuck_volume,
                        "stage_distribution": {s: d["count"] for s, d in stage_analysis.items()}
                    },
                    "stage_bottlenecks": stage_bottlenecks[:5],  # Top 5 problem stages
                    "stuck_deals": sorted(bottlenecks, key=lambda x: x["days_in_stage"], reverse=True)[:10],
                    "at_risk_loans": sorted(at_risk, key=lambda x: x.get("days_over_target", 0), reverse=True)[:10],
                    "guidance": " ".join(guidance_parts)
                }

            except Exception as e:
                logger.error(f"Error fetching SLA dashboard: {e}")
                import traceback
                return {"success": False, "message": f"Error loading SLA data: {str(e)}", "traceback": traceback.format_exc()}

        async def execute_get_efficiency_metrics(args):
            """Get deep pipeline efficiency metrics with root cause analysis"""
            metric_type = args.get("metric_type", "full_analysis")

            # SLA target days by stage
            SLA_TARGETS = {
                "Application": 2, "APPLICATION": 2,
                "Disclosed": 3, "DISCLOSED": 3,
                "Processing": 5, "PROCESSING": 5,
                "Submitted": 2, "SUBMITTED": 2,
                "Conditional": 3, "CONDITIONAL": 3,
                "CTC": 2, "Clear to Close": 2, "CLEAR_TO_CLOSE": 2,
                "Docs": 2, "DOCS": 2,
                "Funding": 1, "FUNDING": 1
            }

            try:
                # Get comprehensive data for analysis
                loan_data = db.execute(
                    text("""
                        SELECT
                            l.id, l.loan_number, l.borrower_name, l.coborrower_name,
                            l.stage::text as stage, l.amount, l.days_in_stage,
                            l.processor, l.underwriter, l.closer,
                            l.closing_date, l.updated_at, l.sla_status
                        FROM loans l
                        WHERE l.loan_officer_id = :user_id
                        AND l.stage::text NOT IN ('Funded', 'Withdrawn', 'Closed', 'FUNDED', 'WITHDRAWN', 'CLOSED')
                    """),
                    {"user_id": current_user.id}
                ).fetchall()

                # Get task data for root cause analysis
                task_data = db.execute(
                    text("""
                        SELECT
                            t.id, t.title, t.status, t.priority, t.due_date,
                            t.loan_id, t.lead_id, t.owner_id,
                            u.full_name as assignee_name,
                            u.email as assignee_email
                        FROM tasks t
                        LEFT JOIN users u ON t.owner_id = u.id
                        WHERE t.status NOT IN ('completed', 'cancelled')
                        AND (t.loan_id IN (SELECT id FROM loans WHERE loan_officer_id = :user_id)
                             OR t.owner_id = :user_id)
                    """),
                    {"user_id": current_user.id}
                ).fetchall()

                # Analyze bottlenecks with root causes
                stage_metrics = {}
                team_workload = {}
                stuck_deals = []
                total_pipeline_value = 0

                for loan in loan_data:
                    stage = str(loan.stage) if loan.stage else "Unknown"
                    days = loan.days_in_stage or 0
                    amount = float(loan.amount) if loan.amount else 0
                    target = SLA_TARGETS.get(stage, 5)
                    total_pipeline_value += amount

                    # Track stage metrics
                    if stage not in stage_metrics:
                        stage_metrics[stage] = {
                            "count": 0, "total_days": 0, "total_volume": 0,
                            "target_days": target, "stuck_count": 0, "loans": []
                        }
                    stage_metrics[stage]["count"] += 1
                    stage_metrics[stage]["total_days"] += days
                    stage_metrics[stage]["total_volume"] += amount
                    stage_metrics[stage]["loans"].append({
                        "borrower_name": loan.borrower_name,
                        "amount": amount,
                        "days_in_stage": days,
                        "processor": loan.processor,
                        "underwriter": loan.underwriter
                    })

                    # Track team workload
                    for role, name in [("processor", loan.processor), ("underwriter", loan.underwriter), ("closer", loan.closer)]:
                        if name:
                            if name not in team_workload:
                                team_workload[name] = {"role": role, "loan_count": 0, "stuck_count": 0, "overdue_tasks": 0, "loans": []}
                            team_workload[name]["loan_count"] += 1
                            team_workload[name]["loans"].append(loan.borrower_name)

                    # Identify stuck deals
                    if days > target * 1.5:
                        stage_metrics[stage]["stuck_count"] += 1
                        # Determine root cause
                        root_cause = "Unknown"
                        if loan.processor and loan.processor in team_workload:
                            root_cause = f"{loan.processor} may be overloaded"
                        elif not loan.processor:
                            root_cause = "No processor assigned"

                        stuck_deals.append({
                            "borrower_name": loan.borrower_name,
                            "amount": amount,
                            "stage": stage,
                            "days_in_stage": days,
                            "target_days": target,
                            "days_over": days - target,
                            "processor": loan.processor,
                            "underwriter": loan.underwriter,
                            "root_cause": root_cause,
                            "closing_date": loan.closing_date.isoformat() if loan.closing_date else None
                        })
                        if loan.processor and loan.processor in team_workload:
                            team_workload[loan.processor]["stuck_count"] += 1

                # Count overdue tasks per team member
                for task in task_data:
                    if task.assignee_name and task.due_date:
                        if task.due_date.date() < datetime.now().date():
                            if task.assignee_name in team_workload:
                                team_workload[task.assignee_name]["overdue_tasks"] += 1

                # Calculate stage bottlenecks with severity
                bottlenecks = []
                for stage, data in stage_metrics.items():
                    if data["count"] > 0:
                        avg_days = data["total_days"] / data["count"]
                        variance = avg_days - data["target_days"]
                        if variance > 0:
                            severity = "critical" if variance > data["target_days"] else ("warning" if variance > data["target_days"] * 0.5 else "minor")

                            # Find root cause
                            root_cause = "Multiple factors"
                            recommendation = "Review individual loans"

                            # Check if one person is overloaded
                            stuck_loans = [l for l in data["loans"] if l["days_in_stage"] > data["target_days"] * 1.5]
                            if stuck_loans:
                                processors = [l["processor"] for l in stuck_loans if l.get("processor")]
                                if processors:
                                    from collections import Counter
                                    most_common = Counter(processors).most_common(1)
                                    if most_common:
                                        overloaded_person = most_common[0][0]
                                        overloaded_count = most_common[0][1]
                                        if overloaded_count >= 2:
                                            overdue_count = team_workload.get(overloaded_person, {}).get("overdue_tasks", 0)
                                            root_cause = f"{overloaded_person} overloaded ({overloaded_count} stuck files, {overdue_count} overdue tasks)"
                                            # Find who to redistribute to
                                            other_processors = [n for n, d in team_workload.items() if d["role"] == "processor" and n != overloaded_person]
                                            if other_processors:
                                                lightest = min(other_processors, key=lambda x: team_workload[x]["loan_count"])
                                                recommendation = f"Redistribute {min(overloaded_count, 3)} files from {overloaded_person} to {lightest}"

                            bottlenecks.append({
                                "stage": stage,
                                "avg_days": round(avg_days, 1),
                                "target_days": data["target_days"],
                                "variance": round(variance, 1),
                                "severity": severity,
                                "affected_deals": data["stuck_count"],
                                "total_volume": data["total_volume"],
                                "root_cause": root_cause,
                                "recommendation": recommendation
                            })

                bottlenecks = sorted(bottlenecks, key=lambda x: x["variance"], reverse=True)

                # Calculate velocity (avg days to close by stage)
                velocity = {stage: round(data["total_days"] / data["count"], 1) if data["count"] > 0 else 0 for stage, data in stage_metrics.items()}

                # Team capacity analysis
                team_capacity = []
                for name, data in team_workload.items():
                    capacity_status = "available" if data["loan_count"] < 8 else ("at_capacity" if data["loan_count"] < 12 else "overloaded")
                    team_capacity.append({
                        "name": name,
                        "role": data["role"],
                        "active_loans": data["loan_count"],
                        "stuck_loans": data["stuck_count"],
                        "overdue_tasks": data["overdue_tasks"],
                        "capacity_status": capacity_status,
                        "recommendation": f"Can take {max(0, 10 - data['loan_count'])} more files" if capacity_status != "overloaded" else "Needs files redistributed"
                    })

                team_capacity = sorted(team_capacity, key=lambda x: x["stuck_loans"], reverse=True)

                # Build response based on metric_type
                response = {
                    "success": True,
                    "metric_type": metric_type,
                    "summary": {
                        "total_active_loans": len(loan_data),
                        "total_pipeline_value": total_pipeline_value,
                        "bottleneck_stages": len([b for b in bottlenecks if b["severity"] == "critical"]),
                        "stuck_deals": len(stuck_deals),
                        "team_members_overloaded": len([t for t in team_capacity if t["capacity_status"] == "overloaded"])
                    }
                }

                if metric_type in ["bottlenecks", "full_analysis"]:
                    response["bottlenecks"] = bottlenecks[:5]
                    response["stuck_deals"] = sorted(stuck_deals, key=lambda x: x["days_over"], reverse=True)[:10]

                if metric_type in ["velocity", "stage_performance", "full_analysis"]:
                    response["velocity_by_stage"] = velocity
                    response["stage_performance"] = [
                        {"stage": s, "count": d["count"], "avg_days": round(d["total_days"]/d["count"], 1) if d["count"] > 0 else 0, "target": d["target_days"], "volume": d["total_volume"]}
                        for s, d in stage_metrics.items()
                    ]

                if metric_type in ["team_capacity", "full_analysis"]:
                    response["team_capacity"] = team_capacity

                # Generate actionable guidance
                guidance = []
                if bottlenecks and bottlenecks[0]["severity"] == "critical":
                    b = bottlenecks[0]
                    guidance.append(f"CRITICAL: {b['stage']} stage is bottlenecked at {b['avg_days']} days (target: {b['target_days']}). {b['root_cause']}. {b['recommendation']}.")
                if stuck_deals:
                    worst = stuck_deals[0]
                    guidance.append(f"Priority: {worst['borrower_name']}'s ${worst['amount']:,.0f} loan is {worst['days_over']} days over SLA in {worst['stage']}.")
                if not guidance:
                    guidance.append("Pipeline efficiency is healthy. No critical bottlenecks detected.")

                response["guidance"] = " ".join(guidance)

                return response

            except Exception as e:
                logger.error(f"Error fetching efficiency metrics: {e}")
                import traceback
                return {"success": False, "message": f"Error: {str(e)}", "traceback": traceback.format_exc()}

        async def execute_get_analytics_report(args):
            """Generate comprehensive analytics report"""
            report_type = args.get("report_type", "pipeline_summary")
            period = args.get("period", "month")
            team_member = args.get("team_member")

            try:
                # Calculate date range
                today = datetime.now().date()
                if period == "today":
                    start_date = today
                elif period == "week":
                    start_date = today - timedelta(days=7)
                elif period == "month":
                    start_date = today - timedelta(days=30)
                elif period == "quarter":
                    start_date = today - timedelta(days=90)
                elif period == "year" or period == "ytd":
                    start_date = datetime(today.year, 1, 1).date()
                else:
                    start_date = today - timedelta(days=30)

                if report_type == "pipeline_summary":
                    leads = db.query(Lead).filter(Lead.owner_id == current_user.id).all()
                    # Use raw SQL for loans to avoid enum issues
                    try:
                        loan_rows = db.execute(
                            text("SELECT id, stage, amount FROM loans WHERE loan_officer_id = :user_id"),
                            {"user_id": current_user.id}
                        ).fetchall()
                    except:
                        loan_rows = []

                    lead_stages = {}
                    for lead in leads:
                        stage = str(lead.stage).replace("LeadStage.", "") if lead.stage else "NEW"
                        lead_stages[stage] = lead_stages.get(stage, 0) + 1

                    loan_stages = {}
                    total_volume = 0
                    for loan in loan_rows:
                        stage = str(loan.stage).replace("LoanStage.", "") if loan.stage else "Unknown"
                        loan_stages[stage] = loan_stages.get(stage, 0) + 1
                        if loan.amount:
                            total_volume += float(loan.amount)

                    return {
                        "success": True,
                        "report_type": "pipeline_summary",
                        "period": period,
                        "metrics": {
                            "total_leads": len(leads),
                            "total_loans": len(loan_rows),
                            "total_volume": total_volume,
                            "lead_stages": lead_stages,
                            "loan_stages": loan_stages,
                            "avg_loan_amount": total_volume / len(loan_rows) if loan_rows else 0
                        }
                    }

                elif report_type == "conversion_funnel":
                    leads = db.query(Lead).filter(Lead.owner_id == current_user.id).all()

                    funnel = {
                        "new_leads": len([l for l in leads if str(l.stage) in ["NEW", "LeadStage.NEW"]]),
                        "qualified": len([l for l in leads if str(l.stage) in ["PROSPECT", "PRE_QUALIFIED", "LeadStage.PROSPECT"]]),
                        "application": len([l for l in leads if str(l.stage) in ["APPLICATION", "APPLICATION_STARTED", "LeadStage.APPLICATION"]]),
                        "processing": len([l for l in leads if str(l.stage) in ["PRE_APPROVED", "UNDER_CONTRACT", "LeadStage.PRE_APPROVED"]]),
                        "closed": len([l for l in leads if str(l.stage) in ["CLOSED", "LeadStage.CLOSED"]])
                    }

                    return {
                        "success": True,
                        "report_type": "conversion_funnel",
                        "funnel": funnel,
                        "conversion_rate": round(funnel["closed"] / funnel["new_leads"] * 100, 1) if funnel["new_leads"] > 0 else 0
                    }

                elif report_type == "activity_summary":
                    activities = db.query(Activity).filter(
                        Activity.user_id == current_user.id,
                        Activity.created_at >= start_date
                    ).all()

                    activity_types = {}
                    for a in activities:
                        atype = a.activity_type or "other"
                        activity_types[atype] = activity_types.get(atype, 0) + 1

                    return {
                        "success": True,
                        "report_type": "activity_summary",
                        "period": period,
                        "total_activities": len(activities),
                        "by_type": activity_types
                    }

                elif report_type == "employee_performance":
                    # Get team members (users) and their loan data
                    try:
                        # Get loans with processor/closer data
                        loan_rows = db.execute(
                            text("""
                                SELECT
                                    l.loan_officer_id,
                                    l.processor,
                                    l.stage,
                                    l.amount,
                                    l.borrower_name,
                                    l.created_at,
                                    l.close_date
                                FROM loans l
                                WHERE l.created_at >= :start_date
                                OR l.close_date >= :start_date
                            """),
                            {"start_date": start_date}
                        ).fetchall()

                        # Aggregate by loan officer
                        lo_stats = {}
                        for row in loan_rows:
                            lo_id = row.loan_officer_id
                            if lo_id not in lo_stats:
                                lo_stats[lo_id] = {
                                    "total_loans": 0,
                                    "total_volume": 0,
                                    "closed": 0,
                                    "processing": 0,
                                    "by_stage": {}
                                }

                            lo_stats[lo_id]["total_loans"] += 1
                            if row.amount:
                                lo_stats[lo_id]["total_volume"] += float(row.amount)

                            stage = str(row.stage).replace("LoanStage.", "") if row.stage else "Unknown"
                            lo_stats[lo_id]["by_stage"][stage] = lo_stats[lo_id]["by_stage"].get(stage, 0) + 1

                            if stage in ["FUNDED", "CLOSED", "CTC"]:
                                lo_stats[lo_id]["closed"] += 1
                            elif stage in ["PROCESSING", "UNDERWRITING", "SUBMITTED"]:
                                lo_stats[lo_id]["processing"] += 1

                        # Get user names
                        team_performance = []
                        for lo_id, stats in lo_stats.items():
                            user = db.query(User).filter(User.id == lo_id).first()
                            team_performance.append({
                                "name": user.full_name if user else f"User {lo_id}",
                                "email": user.email if user else None,
                                "loans": stats["total_loans"],
                                "volume": stats["total_volume"],
                                "closed": stats["closed"],
                                "in_progress": stats["processing"],
                                "by_stage": stats["by_stage"],
                                "conversion_rate": round(stats["closed"] / stats["total_loans"] * 100, 1) if stats["total_loans"] > 0 else 0
                            })

                        # Sort by volume
                        team_performance.sort(key=lambda x: x["volume"], reverse=True)

                        return {
                            "success": True,
                            "report_type": "employee_performance",
                            "period": period,
                            "team": team_performance,
                            "summary": {
                                "total_team_volume": sum(t["volume"] for t in team_performance),
                                "total_loans": sum(t["loans"] for t in team_performance),
                                "total_closed": sum(t["closed"] for t in team_performance),
                                "top_performer": team_performance[0]["name"] if team_performance else "N/A"
                            }
                        }
                    except Exception as e:
                        logger.error(f"Error in employee_performance report: {e}")
                        return {"success": False, "message": f"Error: {str(e)}"}

                else:
                    return {
                        "success": True,
                        "report_type": report_type,
                        "message": f"Report type '{report_type}' is available. Specify period and filters for detailed data."
                    }

            except Exception as e:
                logger.error(f"Error generating analytics report: {e}")
                return {"success": False, "message": f"Error generating report: {str(e)}"}

        async def execute_send_sms(args):
            """Send SMS text message via Twilio"""
            recipient_phone = args.get("recipient_phone")
            recipient_name = args.get("recipient_name")
            message = args.get("message")
            lead_id = args.get("lead_id")
            loan_id = args.get("loan_id")

            if not message:
                return {"success": False, "message": "Message content is required"}

            # Look up phone number if not provided
            if not recipient_phone and recipient_name:
                lead = db.query(Lead).filter(
                    Lead.owner_id == current_user.id,
                    Lead.name.ilike(f"%{recipient_name}%")
                ).first()
                if lead and lead.phone:
                    recipient_phone = lead.phone
                    lead_id = lead.id

            if not recipient_phone:
                return {"success": False, "message": "Phone number required. Provide recipient_phone or a valid recipient_name."}

            # Format phone number
            phone = recipient_phone.replace("-", "").replace(" ", "").replace("(", "").replace(")", "")
            if not phone.startswith("+"):
                phone = "+1" + phone if len(phone) == 10 else "+" + phone

            try:
                # Use Twilio to send SMS
                twilio_sid = os.getenv("TWILIO_ACCOUNT_SID")
                twilio_token = os.getenv("TWILIO_AUTH_TOKEN")
                twilio_phone = os.getenv("TWILIO_PHONE_NUMBER")

                if not all([twilio_sid, twilio_token, twilio_phone]):
                    return {"success": False, "message": "SMS service not configured. Please configure Twilio credentials."}

                from twilio.rest import Client
                client = Client(twilio_sid, twilio_token)

                sms = client.messages.create(
                    body=message,
                    from_=twilio_phone,
                    to=phone
                )

                # Log the activity
                activity = Activity(
                    activity_type="sms_sent",
                    description=f"SMS sent: {message[:100]}...",
                    user_id=current_user.id,
                    lead_id=lead_id,
                    loan_id=loan_id
                )
                db.add(activity)
                db.commit()

                await log_ai_action_to_mission_control(
                    db=db, agent_name="SMS Tool", action_type="send_sms",
                    user_id=current_user.id, context={"phone": phone, "message_preview": message[:50]},
                    autonomy_level="autonomous", status="completed"
                )

                return {"success": True, "message": f"SMS sent to {phone}", "sid": sms.sid}

            except Exception as e:
                logger.error(f"Error sending SMS: {e}")
                return {"success": False, "message": f"Failed to send SMS: {str(e)}"}

