@app.get("/api/v1/leads/")
async def get_leads(
    skip: int = 0,
    limit: int = 100,
    stage: Optional[str] = None,
    db: Session = Depends(get_db),
    current_user: User = Depends(get_current_user_flexible)
):
    try:
        # Phase 3: Apply permission-based filtering
        query = db.query(Lead)
        query = filter_leads_by_permissions(query, current_user, db)

        if stage:
            try:
                stage_enum = LeadStage(stage)
                query = query.filter(Lead.stage == stage_enum)
            except ValueError:
                pass

        leads = query.order_by(Lead.created_at.desc()).offset(skip).limit(limit).all()

        # Convert to dict manually to avoid Pydantic validation issues
        result = []
        for lead in leads:
            lead_dict = {
                "id": lead.id,
                "name": lead.name,
                "email": lead.email,
                "phone": lead.phone,
                "stage": lead.stage.value if lead.stage else None,
                "source": lead.source,
                "ai_score": lead.ai_score,
                "sentiment": lead.sentiment,
                "next_action": lead.next_action,
                "preapproval_amount": lead.preapproval_amount,
                "credit_score": lead.credit_score,
                "loan_type": lead.loan_type,
                "notes": lead.notes,
                "created_at": lead.created_at.isoformat() if lead.created_at else None,
                "updated_at": lead.updated_at.isoformat() if lead.updated_at else None,
            }
            result.append(lead_dict)
        return result
    except Exception as e:
        import traceback
        logger.error(f"get_leads error: {e}")
        logger.error(f"get_leads traceback: {traceback.format_exc()}")
        raise

@app.get("/api/v1/leads/search", response_model=List[LeadResponse])
async def search_leads(
    q: str,
    limit: int = 10,
    db: Session = Depends(get_db),
    current_user: User = Depends(get_current_user_flexible)
):
    """Search leads by name (first name, last name, or full name)"""
    if not q or len(q.strip()) < 2:
        return []

    search_term = q.strip().lower()

    # Build query with permission filtering
    query = db.query(Lead)
    query = filter_leads_by_permissions(query, current_user, db)

    # Search by name (case-insensitive)
    query = query.filter(
        func.lower(Lead.name).contains(search_term)
    )

    # Order by relevance (exact matches first, then alphabetically)
    leads = query.order_by(Lead.name).limit(limit).all()

    return leads

